package util; import jakarta.servlet.*;import java.io.*;import java.sql.*; public class DatabaseInitializer implements ServletContextListener{public void contextInitialized(ServletContextEvent e){for(String n:new String[]{"schema.sql","seed.sql"})try(Connection c=Database.open();Statement s=c.createStatement();InputStream i=getClass().getClassLoader().getResourceAsStream(n)){if(i!=null)for(String q:new String(i.readAllBytes()).split(";"))if(!q.isBlank())s.execute(q);}catch(Exception x){System.err.println("[EasyHealth] "+x.getMessage());}}}
